  "prediction_basis_card_ids": ["C05", "C24", "C08", "C14", "C17"],
  "claims": [
    {
      "claim": "KNI-272, the closest fed-state peptidomimetic context, had absolute oral bioavailability of 36.4% after a 6.6 mg/kg post-prandial capsule (n=2) and 22.06 ± 2.99% after a 4 mg/kg post-prandial capsule (n=5), both at or above the 20% threshold; the below-threshold 15.72 ± 5.96% value came from a 2 mg/kg cherry syrup, indicating dose/formulation dependence rather than a uniform low F.",
      "card_ids": ["C05", "C24", "C17"]
    },
    {
      "claim": "Atazanavir, a fed-state peptidomimetic HIV protease inhibitor with tert-butyl and hydroxyethyl motifs, has oral bioavailability >90% when taken with food; the L2 note of variability with food and gastrointestinal pH does not contradict the fed-state high value.",
      "card_ids": ["C08", "C14", "C18"]
    },
    {
      "claim": "L3 oral exposure records for related HIV protease inhibitors show measurable oral Cmax/AUC, but they are predominantly ritonavir-boosted regimens without IV comparators, so they do not directly establish F ≥ 20% for the query and do not overturn the fed-state high evidence.",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    },
    {
      "claim": "Low-F contexts (argatroban, danavorexton, rifampin-induced propafenone) are not structurally or conditionally transferable to the fed-state query, and physicochemical liabilities alone are not affirmative evidence for F < 20%.",
      "card_ids": ["C03", "C07", "C10"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "Query dose and formulation are unspecified; KNI-272 fed F ranges from 15.72% (2 mg/kg syrup) to 36.4% (6.6 mg/kg capsule), so formulation/dose could affect threshold classification.",
    "L3 oral exposure records are predominantly ritonavir-boosted and lack IV comparators, so they cannot quantify F for the query.",
    "Solubility/dissolution and first-pass metabolism for the query are not experimentally characterized; structural similarity to cited contexts is qualitative.",
    "Atazanavir bioavailability report type is unspecified, and the KNI-272 36.4% value is based on n=2."
  ],
  "decision_summary": "High, low confidence: the most transferable fed-state evidence (KNI-272 post-prandial capsule F 22–36%; atazanavir >90% with food) supports F ≥ 20%, while the below-threshold KNI-272 syrup value reflects dose/formulation dependence; L3 boosted oral-exposure records for related HIV protease inhibitors are not direct F evidence and do not change the decision; low-F contexts are not transferable, and physicochemical liabilities alone do not support a low prediction."
}

